import{_ as a}from"./chunks/Audio.COine8Wh.js";import{_ as r}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as s,j as t,G as i,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Bankruptcy Administration Improvement Act of 2025","description":"","frontmatter":{"legisId":"2026-02-06-bankruptcy-administration-improvement-act-of-2025","title":"Bankruptcy Administration Improvement Act of 2025","displayTitle":"Bankruptcy Administration Improvement Act of 2025","lawNumber":"119-76","billNumber":"S. 3424","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ76.xml","publishDate":"2026-02-06T00:00:00-05:00","industries":["finance","government-operations"],"agencies":["Department of the Treasury","United States Trustee System","United States bankruptcy courts"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Bankruptcy Administration Improvement Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-02-06-bankruptcy-administration-improvement-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Bankruptcy Administration Improvement Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-02-06-bankruptcy-administration-improvement-act-of-2025\\",\\"datePublished\\":\\"2026-02-06T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-02-06-bankruptcy-administration-improvement-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-02-06-bankruptcy-administration-improvement-act-of-2025.md","filePath":"congress-bills/2026-02-06-bankruptcy-administration-improvement-act-of-2025.md","lastUpdated":1788887623000}'),p={name:"congress-bills/2026-02-06-bankruptcy-administration-improvement-act-of-2025.md"},g=Object.assign(p,{setup(c){return(u,e)=>(s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"bankruptcy-administration-improvement-act-of-2025",tabindex:"-1"},[l("Bankruptcy Administration Improvement Act of 2025 "),t("a",{class:"header-anchor",href:"#bankruptcy-administration-improvement-act-of-2025","aria-label":'Permalink to "Bankruptcy Administration Improvement Act of 2025"'},"​")],-1)),i(a),i(r,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Friday, February 6, 2026. Public Law 119-76, S. 3424.</p><p><strong>Headline:</strong> The law doubles Chapter 7 trustee compensation and extends bankruptcy-system funding and judgeships.</p><p><strong>Why it matters:</strong> It strengthens funding for trustees, courts, and bankruptcy administration without raising Chapter 7 filing fees or restricting fee waivers.</p><p><strong>What the law does:</strong></p><ul><li>Raises Chapter 7 trustee compensation from $60 to $120 per eligible case, including cases converted to Chapter 7.</li><li>Applies the compensation increase to covered cases filed on or after the first October 1 following enactment.</li><li>Revises Chapter 11 quarterly fees and sends $5.4 million annually to the Treasury’s general fund from fiscal years 2026 through 2031.</li><li>Continues specified funding for the United States Trustee System and related bankruptcy operations through 2031.</li><li>Extends certain temporary bankruptcy judgeships from five years to ten years.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Chapter 7 bankruptcy trustees.</li><li>Chapter 7 and Chapter 11 bankruptcy filers.</li><li>Bankruptcy courts, temporary bankruptcy judges, and the United States Trustee System.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>People filing Chapter 7 will not face a higher filing fee under this law.</li><li>Indigent filers may still ask courts to waive Chapter 7 filing fees.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="bankruptcy-administration-improvement-act-of-2025-1" tabindex="-1">Bankruptcy Administration Improvement Act of 2025 <a class="header-anchor" href="#bankruptcy-administration-improvement-act-of-2025-1" aria-label="Permalink to &quot;Bankruptcy Administration Improvement Act of 2025&quot;">​</a></h3><p>The law increases total compensation for Chapter 7 bankruptcy trustees from $60 to $120 per case and reallocates bankruptcy fee revenue to support trustees, courts, and the United States Trustee System. It also revises Chapter 11 quarterly fees, continues specified funding arrangements through 2031, and extends certain temporary bankruptcy judgeships from five years to ten years. It does not increase the Chapter 7 filing fee or limit courts’ authority to waive filing fees for indigent individuals.</p><p><strong>Key takeaways:</strong></p><ul><li>Chapter 7 trustees will receive total compensation of $120 per eligible case, including cases converted to Chapter 7.</li><li>The trustee compensation changes apply to covered cases commenced on or after the first October 1 following enactment.</li><li>The law revises Chapter 11 quarterly fee calculations and directs $5.4 million of those fees annually to the Treasury’s general fund for fiscal years 2026 through 2031.</li><li>Specified deposits supporting the United States Trustee System and related bankruptcy operations are continued through 2031.</li><li>Certain temporary bankruptcy judgeships created or continued under earlier laws are extended from five-year terms to ten-year terms.</li><li>The law leaves the Chapter 7 filing fee unchanged and preserves courts’ authority to waive filing fees for indigent individuals.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ76.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ76.xml</a></p>',15))]))}});export{h as __pageData,g as default};
